// src is rows x cols, row-major. Write its transpose into dst,
// which is cols x rows, also row-major: dst[j][i] = src[i][j].
void transpose(const int *src, int *dst, int rows, int cols) {
  for (int k = 0; k < rows * cols; k++) dst[k] = src[k];
}

